{
  "nl": {
    "issue": [
      {
        "text": "收养关系成立后，养子女与养父母、养父母的近亲属、生父母及其他近亲属之间的权利义务关系如何确定",
        "rules": ["c1111-1", "c1111-2", "c1111-3"]
      },
      {
        "text": "养子女的姓氏如何确定",
        "rules": ["c1112-1", "c1112-2"]
      },
      {
        "text": "收养关系在何种条件下可以解除、由谁主张、如何主张",
        "rules": ["c1114-1", "c1114-agreed", "c1114-consent", "c1114-ground", "c1114-2", "c1114-3"]
      },
      {
        "text": "收养关系解除后，身份关系与财产关系如何处理",
        "rules": ["c1117-1", "c1117-2", "c1117-3", "c1117-4", "c1118-1", "c1118-2", "c1118-3"]
      }
    ],
    "conditions": [
      {
        "text": "收养关系已依法成立（自成立之日起发生身份效力）",
        "rules": ["c1111-1", "c1111-2", "c1111-3"]
      },
      {
        "text": "被收养人尚未成年",
        "rules": ["c1114-1", "c1114-agreed", "c1114-ground"]
      },
      {
        "text": "收养人不履行抚养义务，或有虐待、遗弃等侵害未成年养子女合法权益的行为",
        "rules": ["c1114-ground"]
      },
      {
        "text": "送养人、收养人不能达成解除收养关系的协议",
        "rules": ["c1114-3"]
      },
      {
        "text": "养子女已满八周岁（解除时须征得本人同意）",
        "rules": ["c1114-consent"]
      },
      {
        "text": "收养关系已解除",
        "rules": ["c1117-1", "c1117-2", "c1117-3", "c1117-4", "c1118-1", "c1118-2", "c1118-3"]
      },
      {
        "text": "经养父母抚养的成年养子女，养父母缺乏劳动能力又缺乏生活来源",
        "rules": ["c1118-1"]
      },
      {
        "text": "因养子女成年后虐待、遗弃养父母而解除收养关系",
        "rules": ["c1118-2"]
      },
      {
        "text": "生父母要求解除收养关系",
        "rules": ["c1118-3"]
      }
    ],
    "exceptions": [
      {
        "text": "收养人、送养人双方协议解除的，不受“被收养人成年以前不得解除”的限制",
        "rules": ["c1114-agreed"]
      },
      {
        "text": "成年养子女与生父母及其他近亲属的权利义务关系是否恢复，可以协商确定，不适用自行恢复",
        "rules": ["c1117-4"]
      },
      {
        "text": "因养父母虐待、遗弃养子女而解除收养关系的，养父母不得要求生父母补偿收养期间支出的抚养费",
        "rules": ["c1118-3"]
      }
    ],
    "effects": [
      {
        "text": "养父母与养子女间的权利义务关系适用本法关于父母子女关系的规定；养子女与养父母近亲属间的权利义务关系适用本法关于子女与父母近亲属关系的规定",
        "rules": ["c1111-1", "c1111-2"]
      },
      {
        "text": "养子女与生父母以及其他近亲属间的权利义务关系，因收养关系的成立而消除",
        "rules": ["c1111-3"]
      },
      {
        "text": "养子女可以随养父或者养母的姓氏；经当事人协商一致，也可以保留原姓氏",
        "rules": ["c1112-1", "c1112-2"]
      },
      {
        "text": "收养人在被收养人成年以前不得解除收养关系；养子女八周岁以上的，应当征得本人同意",
        "rules": ["c1114-1", "c1114-consent"]
      },
      {
        "text": "收养人不履行抚养义务或有虐待、遗弃等侵害行为的，送养人有权要求解除收养关系；不能达成协议的，可以向人民法院提起诉讼",
        "rules": ["c1114-2", "c1114-3"]
      },
      {
        "text": "解除后，养子女与养父母及其他近亲属间的权利义务关系即行消除；未成年养子女与生父母及其他近亲属间的权利义务关系自行恢复",
        "rules": ["c1117-1", "c1117-2", "c1117-3"]
      },
      {
        "text": "经养父母抚养的成年养子女，对缺乏劳动能力又缺乏生活来源的养父母，应当给付生活费",
        "rules": ["c1118-1"]
      },
      {
        "text": "因养子女成年后虐待、遗弃养父母而解除的，养父母可以要求养子女补偿收养期间支出的抚养费",
        "rules": ["c1118-2"]
      },
      {
        "text": "生父母要求解除收养关系的，养父母可以要求生父母适当补偿收养期间支出的抚养费",
        "rules": ["c1118-3"]
      }
    ],
    "priority": [
      {
        "text": "第1114条第2款规定的送养人解除权与起诉权，优先于第1款“成年以前不得解除”的一般禁止",
        "rules": ["c1114-2", "c1114-3"]
      },
      {
        "text": "双方协议解除是“成年以前不得解除”的法定例外，优先于该禁止性规定",
        "rules": ["c1114-agreed"]
      },
      {
        "text": "成年养子女与生父母及其他近亲属关系是否恢复由协商确定，优先于自行恢复的规则",
        "rules": ["c1117-4"]
      },
      {
        "text": "收养关系成立后与生父母及其他近亲属关系消除，优先于父母子女关系的一般规定",
        "rules": ["c1111-3"]
      }
    ],
    "distinguish": [
      {
        "text": "第1112条只涉及姓氏这一身份象征，不改变第1111条确立的权利义务继受体系",
        "rules": []
      },
      {
        "text": "第1110条（收养秘密）、第1113条（收养行为无效）与本条不同：前者保护隐私，后者否定收养效力，均非权利义务的继受机制",
        "rules": []
      },
      {
        "text": "笔记把解除的后果分为身份上效力（拟制血亲消除、自然血亲恢复）与财产上效力（生活费给付、抚养费补偿），与第1117、1118条对应",
        "rules": []
      },
      {
        "text": "LEGO卡片称收养成立的效果“具有溯及力”，与第1111条“自收养关系成立之日起”不符，不予采纳",
        "rules": []
      }
    ]
  },
